def get_price(pid):
    cached = redis.get(f"price:{pid}")
    if cached is not None:
        return cached
    price = db.query_one("SELECT price FROM products WHERE id = %s", pid)
    redis.set(f"price:{pid}", price, ex=3600)
    return price

def update_price(pid, new_price):
    db.execute("UPDATE products SET price = %s WHERE id = %s", new_price, pid)

def allow(user_id):
    key = f"rate:{user_id}"
    count = redis.incr(key)
    if count == 1:
        redis.expire(key, 60)      # start a 60-second window
    return count <= 100
